// Top-customers report for the finance dashboard.
// orders: [{ id, customerId, status, amountCents, currency: 'USD' | 'EUR', createdAt: ISO-8601 string }]
const EUR_TO_USD = 1.08;

function byRank(a, b) {
  if (a.spendCents !== b.spendCents) return b.spendCents - a.spendCents;
  if (a.firstOrderAt !== b.firstOrderAt) return a.firstOrderAt < b.firstOrderAt ? -1 : 1;
  return a.customerId < b.customerId ? -1 : a.customerId > b.customerId ? 1 : 0;
}

function addOrder(group, order) {
  group.orderCount++;
  if (order.createdAt < group.firstOrderAt) group.firstOrderAt = order.createdAt;
  if (order.status === 'paid') {
    group.spendCents += order.currency === 'EUR' ? Math.round(order.amountCents * EUR_TO_USD) : order.amountCents;
  }
}

function newGroup(order) {
  return { customerId: order.customerId, spendCents: 0, orderCount: 0, firstOrderAt: order.createdAt };
}

function summarize(orders, limit = 10) {
  // Fast path: one pass with a Set/Map, then a single sort. For string customer ids,
  // string timestamps and finite spend, byRank is a strict total order, so one final
  // sort gives exactly the order the original sort-after-every-order loop produced.
  const seen = new Set();
  const byCustomer = new Map();
  for (const order of orders) {
    // Upstream retries can deliver the same order twice.
    if (seen.has(order.id)) continue;
    seen.add(order.id);
    if (order.status === 'refunded') continue;
    if (typeof order.customerId !== 'string') return summarizeIncremental(orders, limit);

    let group = byCustomer.get(order.customerId);
    if (!group) {
      group = newGroup(order);
      byCustomer.set(order.customerId, group);
    }
    addOrder(group, order);
  }
  const ranked = [];
  for (const g of byCustomer.values()) {
    if (!(g.spendCents > 0)) continue;
    if (!Number.isFinite(g.spendCents) || typeof g.firstOrderAt !== 'string') return summarizeIncremental(orders, limit);
    ranked.push(g);
  }
  return ranked
    .sort(byRank)
    .slice(0, limit)
    .map((g, i) => ({ rank: i + 1, ...g }));
}

// Original algorithm, kept for malformed input (non-string ids/timestamps, non-finite
// amounts) where byRank has ties or is inconsistent and the result depends on the
// history of incremental sorts. Quadratic; never hit by well-formed orders.
function summarizeIncremental(orders, limit) {
  const seen = [];
  const groups = [];
  for (const order of orders) {
    if (seen.includes(order.id)) continue;
    seen.push(order.id);
    if (order.status === 'refunded') continue;

    let group = groups.find((g) => g.customerId === order.customerId);
    if (!group) {
      group = newGroup(order);
      groups.push(group);
    }
    addOrder(group, order);
    groups.sort(byRank);
  }
  return groups
    .filter((g) => g.spendCents > 0)
    .slice(0, limit)
    .map((g, i) => ({ rank: i + 1, ...g }));
}

module.exports = { summarize };
